#!/usr/bin/env node
// Realism-formula A/B eval — current tuned formula vs raw-UGC scaffold,
// both on the SAME model: gemini-3.1-flash-lite-image (the app's sceneImageModel).
//
// Question under test: the believability pack's 8-block raw-ugc scaffold
// (workflows/believability-samples/ugc-photoreal-prompt-pack.md) went 10/10
// World Cup grade — but ONLY on gpt-image-2. Does it also beat the current
// tuned "Aspirational UGC" formula when generated by Gemini flash-lite?
//
// Arms (same model, same aspect, same quality — only the prompt formula varies):
//   A "current"  — verbatim tuned blocks from services/geminiService.ts
//                  (generateAvatar prompt for the avatar case; scene prompt +
//                  REALISM_INSTRUCTION + NO_TEXT_CONSTRAINT for scene cases).
//   B "scaffold" — verbatim prompts from ugc-photoreal-prompt-pack.md.
//
// Read-only w.r.t. the app: never touches geminiService.ts. Any formula update
// after grading is a separate, Neil-gated TUNED-file proposal.
//
// Usage:
//   node tools/eval_realism_formula.mjs --dry-run
//   node tools/eval_realism_formula.mjs
//   node tools/eval_realism_formula.mjs --only 01-avatar-sari-sari
//   node tools/eval_realism_formula.mjs --arms scaffold
//
// Output: .tmp/realism-formula-eval/<caseId>-<current|scaffold>.png
//         + manifest.json + index.html (side-by-side viewer for grading)
// Secrets: GEMINI_API_KEY from environment or repo-root .env.

import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { resolve, dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const OUT_DIR = join(REPO_ROOT, '.tmp', 'realism-formula-eval');

const MODEL_ID = 'gemini-3.1-flash-lite-image';
const MODEL_FALLBACK = 'gemini-3.1-flash-lite-image-preview';
const API_BASE = 'https://generativelanguage.googleapis.com/v1beta/models';
const CALL_TIMEOUT_MS = 55_000;
const ASPECT = '9:16';
const IMAGE_SIZE = '1K'; // flash-lite is 1K-only (geminiService.ts clamp)

// ============================================================================
// ARM A — VERBATIM COPIES of TUNED blocks from services/geminiService.ts.
// Source of truth is geminiService.ts; if these drift, re-sync before trusting
