// ============================================================================
// Transport — direct v1beta REST, mirrors api/gemini/image.ts (same pattern as
// tools/eval_scene_image_models.mjs).
// ============================================================================

async function callGeminiOnce(modelId, promptText, apiKey) {
    const body = {
        contents: [{ parts: [{ text: promptText }] }],
        generationConfig: {
            responseModalities: ['TEXT', 'IMAGE'],
            imageConfig: { aspectRatio: ASPECT, imageSize: IMAGE_SIZE },
        },
        safetySettings: SAFETY_SETTINGS,
    };
    const url = `${API_BASE}/${modelId}:generateContent?key=${apiKey}`;
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), CALL_TIMEOUT_MS);
    let res;
    try {
        res = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(body),
            signal: ctrl.signal,
        });
    } finally {
        clearTimeout(timer);
    }
    const text = await res.text();
    let json;
    try { json = JSON.parse(text); } catch { json = null; }
    if (!res.ok) {
        const err = new Error(`HTTP ${res.status}: ${text.slice(0, 300)}`);
        err.status = res.status;
        err.body = json;
        throw err;
    }
    const parts = json?.candidates?.[0]?.content?.parts ?? [];
    let imageB64 = null;
    let textPart = null;
    for (const p of parts) {
        if (p.inlineData?.data && !imageB64) imageB64 = p.inlineData.data;
        if (p.text && !textPart) textPart = p.text;
    }
    return { imageB64, textPart };
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function callGeminiRetry(modelId, promptText, apiKey) {
    const backoffs = [2000, 8000];
    let lastErr;
    for (let attempt = 0; attempt < 3; attempt++) {
        try {
            return await callGeminiOnce(modelId, promptText, apiKey);
        } catch (e) {
            lastErr = e;
            const retryable = e.status === 429 || (e.status >= 500 && e.status < 600) || e.name === 'AbortError';
            if (!retryable || attempt === 2) throw e;
            const wait = backoffs[attempt] ?? 8000;
            console.log(`  [retry] ${modelId} attempt ${attempt + 1} failed (${e.status ?? e.name}); waiting ${wait}ms`);
            await sleep(wait);
        }
    }
    throw lastErr;
}

const isNotFound = (e) => e?.status === 404 ||
    /NOT_FOUND/i.test(JSON.stringify(e?.body ?? '')) ||
    /NOT_FOUND|not found/i.test(e?.message ?? '');

async function callGeminiWithFallback(promptText, apiKey) {
    try {
        const out = await callGeminiRetry(MODEL_ID, promptText, apiKey);
        return { ...out, modelId: MODEL_ID };
    } catch (e) {
        if (isNotFound(e)) {
            console.log(`  [fallback] ${MODEL_ID} not found — retrying with ${MODEL_FALLBACK}`);
            const out = await callGeminiRetry(MODEL_FALLBACK, promptText, apiKey);
            return { ...out, modelId: MODEL_FALLBACK };
        }
        throw e;
    }
}

async function loadEnvKey(name) {
    if (process.env[name]) return process.env[name];
    try {
        const envText = await readFile(join(REPO_ROOT, '.env'), 'utf8');
        for (const line of envText.split(/\r?\n/)) {
            const t = line.trim();
            if (t.startsWith(`${name}=`)) return t.slice(name.length + 1).trim().replace(/^['"]|['"]$/g, '');
        }
    } catch { /* no .env */ }
    return null;
}

// ============================================================================
// Side-by-side HTML viewer
// ============================================================================

const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

function buildViewerHtml(manifest) {
    const rows = CASES.map((c) => {
        const r = manifest.cases[c.id]?.results ?? {};
        const cell = (arm, label) => {
            const res = r[arm];
            const img = res?.file
                ? `<img src="${res.file}" alt="${c.id}-${arm}">`
                : `<div class="fail">FAILED: ${esc(res?.error ?? 'not run')}</div>`;
            return `<div class="cell"><h3>${label}</h3>${img}<p class="meta">${res?.modelId ?? ''} ${res?.latencyMs ? `· ${res.latencyMs}ms` : ''}</p></div>`;
        };
        return `
        <section>
          <h2>${c.id} — ${esc(c.surface)}</h2>
          <p class="notes">${esc(c.gradingNotes)}</p>
          <div class="pair">
            ${cell('current', 'A — CURRENT tuned formula (Aspirational UGC)')}
            ${cell('scaffold', 'B — NEW raw-UGC scaffold (believability pack)')}
          </div>
        </section>`;
    }).join('\n');

    return `<!doctype html><html><head><meta charset="utf-8">
<title>Realism formula A/B — gemini-3.1-flash-lite-image</title>
<style>
  body { background:#0b0b0d; color:#eee; font-family:system-ui,sans-serif; margin:2rem; }
  h1 { font-size:1.3rem; } h2 { font-size:1.05rem; margin:2.5rem 0 .3rem; color:#FFCC00; }
  .notes { color:#aaa; font-size:.85rem; max-width:70ch; }
  .pair { display:flex; gap:1.5rem; flex-wrap:wrap; }
  .cell { flex:1; min-width:280px; max-width:420px; }
  .cell h3 { font-size:.85rem; color:#ccc; }
  img { width:100%; border-radius:8px; border:1px solid #333; }
  .meta { color:#777; font-size:.75rem; }
  .fail { padding:2rem 1rem; border:1px dashed #a33; color:#e88; border-radius:8px; font-size:.8rem; }
</style></head><body>
<h1>Realism formula A/B — both arms on <code>${MODEL_ID}</code> · ${ASPECT} · ${IMAGE_SIZE}</h1>
<p class="notes">A = current tuned formula (verbatim from geminiService.ts). B = raw-UGC scaffold (verbatim from ugc-photoreal-prompt-pack.md, 10/10 on gpt-image-2). Grade each pair: which reads more REAL at feed-scroll speed and on direct inspection? Note per-case verdicts back into the prompt pack.</p>
${rows}
</body></html>`;
}

// ============================================================================
// Main
// ============================================================================

function parseArgs(argv) {
    const args = argv.slice(2);
    const dryRun = args.includes('--dry-run');
    const onlyIdx = args.indexOf('--only');
    const only = onlyIdx >= 0 ? args[onlyIdx + 1] : null;
    const armsIdx = args.indexOf('--arms');
    const arms = armsIdx >= 0
        ? args[armsIdx + 1].split(',').map((s) => s.trim()).filter(Boolean)
        : ['current', 'scaffold'];
    for (const a of arms) {
        if (a !== 'current' && a !== 'scaffold') { console.error(`Unknown arm "${a}" (valid: current, scaffold)`); process.exit(1); }
    }
    return { dryRun, only, arms };
}

async function main() {
    const { dryRun, only, arms } = parseArgs(process.argv);
    const apiKey = await loadEnvKey('GEMINI_API_KEY');
    if (!dryRun && !apiKey) {
        console.error('GEMINI_API_KEY not found (env or .env). Use --dry-run to plan without a key.');
        process.exit(2);
    }

    await mkdir(OUT_DIR, { recursive: true });
    const cases = only ? CASES.filter((c) => c.id === only) : CASES;
    if (only && cases.length === 0) {
        console.error(`--only "${only}" matched no case. Valid ids: ${CASES.map((c) => c.id).join(', ')}`);
        process.exit(1);
    }

    console.log(`\n=== realism-formula A/B ${dryRun ? '(DRY RUN — no API calls)' : ''} ===`);
    console.log(`model: ${MODEL_ID} | arms: ${arms.join(', ')} | cases: ${cases.length}\n`);

    const manifest = {
        run: { timestamp: new Date().toISOString(), dryRun, modelId: MODEL_ID, aspect: ASPECT, imageSize: IMAGE_SIZE, arms },
        cases: {},
    };
    let totalOk = 0, totalFail = 0;

    for (const c of cases) {
        manifest.cases[c.id] = { surface: c.surface, gradingNotes: c.gradingNotes, results: {} };
        for (const arm of arms) {
            const promptText = c[arm];
            if (dryRun) {
                console.log(`--- [DRY] ${c.id} | ${arm} | promptChars=${promptText.length}`);
                console.log(promptText.split('\n').map((l) => '    ' + l).join('\n') + '\n');
                manifest.cases[c.id].results[arm] = { planned: true, promptChars: promptText.length };
                continue;
            }
            const outFile = join(OUT_DIR, `${c.id}-${arm}.png`);
            const t0 = Date.now();
            try {
                const { imageB64, textPart, modelId } = await callGeminiWithFallback(promptText, apiKey);
                const latencyMs = Date.now() - t0;
                if (imageB64) {
                    await writeFile(outFile, Buffer.from(imageB64, 'base64'));
                    totalOk++;
                    console.log(`  [ok]   ${c.id} | ${arm} (${modelId}) | ${latencyMs}ms`);
                    manifest.cases[c.id].results[arm] = { file: `${c.id}-${arm}.png`, modelId, latencyMs, promptChars: promptText.length };
                } else {
                    totalFail++;
                    console.log(`  [nofx] ${c.id} | ${arm} (${modelId}) | ${latencyMs}ms | no image part`);
                    manifest.cases[c.id].results[arm] = { file: null, modelId, latencyMs, error: 'no_image_part', textPart: textPart ?? null };
                }
            } catch (e) {
                const latencyMs = Date.now() - t0;
                totalFail++;
                console.log(`  [err]  ${c.id} | ${arm} | ${latencyMs}ms | ${e.message}`);
                manifest.cases[c.id].results[arm] = { file: null, latencyMs, error: e.message };
            }
        }
    }

    await writeFile(join(OUT_DIR, 'manifest.json'), JSON.stringify(manifest, null, 2));
    await writeFile(join(OUT_DIR, 'index.html'), buildViewerHtml(manifest));

    console.log('\n=== summary ===');
    console.log(`ok: ${totalOk} | fail: ${totalFail}`);
    console.log(`viewer:   ${join(OUT_DIR, 'index.html')}`);
    console.log(`manifest: ${join(OUT_DIR, 'manifest.json')}`);
}

main().catch((e) => { console.error(e); process.exit(1); });
